using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using RoadGunner;using RoadGunner.Editor;
public static class ConceptFinalAudit {
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop Play for saved-scene audit");var l=RoadGunnerLevelAuthoring.Current;var s=l.session;var ts=l.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var rs=ts.SelectMany(t=>t.GetComponents<Renderer>()).ToArray();var fs=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).ToArray();var lines=new List<string>();int fail=0;Action<string,bool,string> check=(n,ok,d)=>{if(!ok)fail++;lines.Add((ok?"PASS ":"FAIL ")+n+": "+d);};var issues=RoadGunnerLevelAuthoring.Validate(l).ToArray();check("Level authoring validation",!issues.Any(x=>x.type==MessageType.Error),string.Join(" | ",issues.Select(x=>x.type+" "+x.text)));
 check("No missing scripts",ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))==0,ts.Length+" transforms inspected");check("No missing visual or collision meshes",fs.All(f=>f.sharedMesh)&&ts.SelectMany(t=>t.GetComponents<MeshCollider>()).All(c=>c.sharedMesh),fs.Length+" visual mesh filters");check("No missing or unsupported materials/shaders",rs.All(r=>r.sharedMaterials.Length>0&&r.sharedMaterials.All(m=>m&&m.shader&&m.shader.isSupported&&!m.shader.name.Contains("Error"))),rs.Length+" renderers, including inactive reserves and retired visuals");
 check("Pool and placed population retained",s.spawns.pool.Length==49&&s.spawns.authoredRaiders.Length==19&&s.spawns.buggyPool.Length==3&&s.pickups.items.Length==60&&s.spawns.tuning.activeCap==30,"49 humans,19 authored,3 buggy,60 pickup slots,cap30");check("Spawnable family updated",s.spawns.pool.All(r=>r.visual&&r.visual.name.StartsWith("Concept raider rig")&&r.torso&&r.leftLeg&&r.rightLeg&&r.leftArm&&r.rightArm)&&s.spawns.buggyPool.All(b=>b.armor.All(r=>r))&&s.pickups.gearVisuals.All(v=>v)&&s.pickups.scrapVisuals.All(v=>v),"All mapped refs non-null, three shared raider variants");
 var repair=UnityEngine.Object.FindAnyObjectByType<RepairWorkshop>();check("Workshop contract retained",repair.healingRadius==10&&repair.maximumHealthFractionPerSecond==.1f&&repair.session==s&&repair.activeRepairEffect&&repair.radiusMarking&&repair.repairingLabel,"center="+repair.transform.position+",10m,.1 maxHP/s");check("Original portrait camera retained",s.follow.GetComponent<Camera>().orthographicSize==16&&s.follow.distance==35&&Mathf.Abs(s.follow.damping-.2f)<.0001f,"ortho16,distance35,follow damping.2");check("Terrain and navigation retained",l.appliedFootprintScale==2.5f&&!l.navigationNeedsBake&&l.ground.sharedMesh==l.ground.GetComponent<MeshCollider>().sharedMesh,"local bounds="+l.ground.sharedMesh.bounds+", gameplay="+l.gameplayBounds);
 var accents=l.decorationRoot.Find("Concept route-shoulder composition");check("Nonblocking shoulder family",accents&&accents.childCount==79&&accents.GetComponentsInChildren<Collider>(true).Length==0,"79 compositions; no colliders");var v=UnityEngine.Object.FindAnyObjectByType<UnityEngine.Rendering.Volume>();check("Concept daylight active",v.enabled&&v.isGlobal&&v.sharedProfile.name=="Concept Warm Daylight"&&RenderSettings.sun&&Mathf.Abs(RenderSettings.sun.intensity-1.65f)<.001f,"profile enabled;sun1.65;softshadows;palette atlas");
 check("Saved scene",!l.gameObject.scene.isDirty,l.gameObject.scene.path);lines.Insert(0,"Saved-scene audit / failures="+fail);string output=string.Join("\n",lines);File.WriteAllText("/Users/arthuri/Documents/Codex/2026-10-09/macbook-app-store/outputs/concept-overhaul-2026-10-16/FinalSceneAudit.txt",output);return output;}
}
